from django.db import models
from django import forms
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib import messages

class Article(models.Model):
    titre = models.CharField(max_length=200)
    contenu = models.TextField()
    image = models.ImageField(upload_to='articles/', blank=True, null=True)
    date_creation = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return self.titre

class ArticleForm(forms.ModelForm):
    class Meta:
        model = Article
        fields = ['titre', 'contenu', 'image']
        widgets = {
            'contenu': forms.Textarea(attrs={'rows': 10, 'cols': 80}),
        }

    def clean_titre(self):
        titre = self.cleaned_data['titre']
        if len(titre) < 5:
            raise forms.ValidationError("Le titre doit contenir au moins 5 caractères.")
        return titre

def article_liste(request):
    articles = Article.objects.all().order_by('-date_creation')
    return render(request, 'blog/liste.html', {'articles': articles})

def article_detail(request, pk):
    article = get_object_or_404(Article, pk=pk)
    return render(request, 'blog/detail.html', {'article': article})

def article_creer(request):
    if request.method == 'POST':
        form = ArticleForm(request.POST, request.FILES)
        if form.is_valid():
            article = form.save()
            messages.success(request, "L'article a été publié avec succès.")
            return redirect('article-detail', pk=article.pk)
    else:
        form = ArticleForm()
    return render(request, 'blog/form.html', {'form': form})

def article_modifier(request, pk):
    article = get_object_or_404(Article, pk=pk)
    if request.method == 'POST':
        form = ArticleForm(request.POST, request.FILES, instance=article)
        if form.is_valid():
            article = form.save()
            messages.success(request, "L'article a été modifié avec succès.")
            return redirect('article-detail', pk=article.pk)
    else:
        form = ArticleForm(instance=article)
    return render(request, 'blog/form.html', {'form': form})
